 auto codec=encode_legacy_control_decision_source_v3(quote.value.decision);auto cold=decode_legacy_control_decision_source_v3(codec);check(cold.ok&&validate_collateral_control_decision(x,cold.value,decision.value).ok,"actual original recognition and Known proof survive cold source codec");
